const raw = $input.first().json.output;

const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const data = JSON.parse(cleaned);

return data.new_jobs.map(job => ({
  json: job
}));

const rows = $input.all();

function escapeHtml(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function formatText(value) {
  if (!value) return "";

  return escapeHtml(value)
    .replace(/\\n/g, "<br>")
    .replace(/\n/g, "<br>");
}

